package com.example.HMS.service;

import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestTemplate;

import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoMoreInteractions;

class webhookServiceTest {

    // GreyTest trace: sendWebhook | STMT-1 | BR-163 -> TP-091 -> TC-400
    @Test
    void sendWebhook_addsEventNameToPayload() {
        // Arrange
        RestTemplate restTemplate = mock(RestTemplate.class);
        webhookService service = new webhookService(restTemplate);
        String url = "https://example.test/webhook";
        Map<String, Object> payload = new HashMap<>();
        payload.put("event", "old-event");
        payload.put("recordId", 20);
        Map<String, Object> expectedBeforeCall = new HashMap<>(payload);

        // Act
        service.sendWebhook(url, Thread.State.valueOf("APPOINTMENT_COMPLETED"), payload);

        // Assert
        assertEquals("APPOINTMENT_COMPLETED", payload.get("event"));
        assertEquals(expectedBeforeCall.get("recordId"), payload.get("recordId"));
        verify(restTemplate).postForObject(eq(url), eq(payload), eq(String.class));
        verifyNoMoreInteractions(restTemplate);
    }
}
